function createProductCard(product, isDeal = false) {
    const rating = '★'.repeat(product.rating) + '☆'.repeat(5 - product.rating);
    const dataAttr = isDeal ? `data-deal-product="${product.id}"` : `data-product-id="${product.id}"`;

    return `
        <div class="product-card ${isDeal ? '' : ''}" ${dataAttr}>
            <div class="product-image">
                ${product.image}
                ${isDeal ? `<div class="product-badge deal-badge">${product.discount} OFF</div>` : ''}
            </div>
            <div class="product-info">
                <div class="product-category">${product.category}</div>
                <h3 class="product-title">${product.title}</h3>
                <p class="product-description">${product.description}</p>
                <div class="product-rating">${rating}</div>
                <div class="product-pricing">
                    <span class="price">$${product.price}</span>
                    <span class="original-price">$${product.originalPrice}</span>
                </div>
                <div class="product-action">
                    <button class="add-btn" onclick="addToCart(event, ${product.id}, '${product.title}', ${product.price})">Add to Cart</button>
                    <button class="wishlist-btn" onclick="toggleWishlist(event)">♡</button>
                </div>
            </div>
        </div>
    `;
}

// Open Product Modal
function openProductModal(product) {
    const modal = document.getElementById('product-modal');
    document.getElementById('modal-image').textContent = product.image;
    document.getElementById('modal-title').textContent = product.title;
    document.getElementById('modal-description').textContent = product.description;
    document.getElementById('modal-price').textContent = `$${product.price}`;
    document.getElementById('modal-original-price').textContent = `$${product.originalPrice}`;

    document.getElementById('modal-add-to-cart').onclick = function() {
        addToCart(null, product.id, product.title, product.price);
    };

    modal.style.display = 'block';
}

// Close Modal
function closeModal() {
    document.getElementById('product-modal').style.display = 'none';
}

// Setup Event Listeners
function setupEventListeners() {
    // Modal close button
    document.querySelector('.modal-close').addEventListener('click', closeModal);

    // Click outside modal to close
    window.addEventListener('click', function(event) {
        const modal = document.getElementById('product-modal');
        if (event.target === modal) {
            modal.style.display = 'none';
        }
    });

    // Newsletter form
    document.getElementById('newsletter-form').addEventListener('submit', function(e) {
